function redactedEnv(): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) {
    out[k] = SECRET_KEYS.has(k) ? "[redacted]" : (v ?? "");
  }
  return out;
}

const app = fastify({
  logger: {
    redact: [
      "env.DATABASE_URL",
      "env.STRIPE_SECRET_KEY",
      "env.ANTHROPIC_API_KEY",
      "env.JWT_SECRET",
    ],
  },
});
